// API endpoints
export const API_ENDPOINTS = {
  // Auth endpoints
  LOGIN: '/api/auth/login',
  REGISTER: '/api/auth/register',
  VERIFY: '/api/auth/verify',
  PROFILE: '/api/auth/profile',
  
  // Vendor endpoints
  VENDOR_PROFILE: '/api/vendor/profile',
  VENDOR_APPLICATION: '/api/vendor/application',
  VENDOR_APPLICATIONS: '/api/vendor/applications',
  VENDOR_DASHBOARD: '/api/vendor/dashboard',
  
  // Admin endpoints
  ADMIN_VENDORS: '/api/admin/vendors',
  ADMIN_APPLICATIONS: '/api/admin/applications',
  ADMIN_DASHBOARD: '/api/admin/dashboard',
  
  // Public endpoints
  ADD_VENDOR: '/addVendor',
  GET_ALL_VENDORS: '/getAllVendors'
};

// User roles
export const USER_ROLES = {
  ADMIN: 'ROLE_ADMIN',
  VENDOR: 'ROLE_VENDOR',
  USER: 'ROLE_USER'
};

// Application statuses
export const APPLICATION_STATUS = {
  DRAFT: 'DRAFT',
  SUBMITTED: 'SUBMITTED',
  UNDER_REVIEW: 'UNDER_REVIEW',
  APPROVED: 'APPROVED',
  REJECTED: 'REJECTED',
  INSPECTION_SCHEDULED: 'INSPECTION_SCHEDULED',
  INSPECTION_COMPLETED: 'INSPECTION_COMPLETED',
  LICENSED: 'LICENSED'
};

// Operating regions
export const OPERATING_REGIONS = ['Chennai', 'Bangalore'];

// Form validation messages
export const VALIDATION_MESSAGES = {
  REQUIRED: 'This field is required',
  EMAIL_INVALID: 'Please enter a valid email address',
  PASSWORD_TOO_SHORT: 'Password must be at least 8 characters',
  PASSWORDS_DONT_MATCH: 'Passwords do not match',
  PHONE_INVALID: 'Please enter a valid phone number',
  REGION_INVALID: 'Please select a valid operating region'
};

// Success messages
export const SUCCESS_MESSAGES = {
  LOGIN_SUCCESS: 'Login successful',
  REGISTER_SUCCESS: 'Registration successful. Please check your email for verification.',
  PROFILE_UPDATED: 'Profile updated successfully',
  APPLICATION_SUBMITTED: 'Application submitted successfully',
  PROFILE_CREATED: 'Profile created successfully'
};

// Error messages
export const ERROR_MESSAGES = {
  GENERIC_ERROR: 'Something went wrong. Please try again.',
  NETWORK_ERROR: 'Network error. Please check your connection.',
  UNAUTHORIZED: 'You are not authorized to perform this action.',
  LOGIN_FAILED: 'Invalid username or password',
  PROFILE_INCOMPLETE: 'Please complete your profile first',
  TOKEN_EXPIRED: 'Your session has expired. Please login again.'
};
